<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ArrowRight, BookOpen, BriefcaseBusiness, CalendarPlus, Check, CheckCircle2, Dumbbell, HeartPulse, ListChecks, ListPlus, Pause, Play, Plus, RefreshCw, Sparkles } from 'lucide-vue-next'
import { api } from '../../shared/api/client'
import { encouragement } from '../../shared/encouragement'

type Goal={publicId:string;dimensionPublicId:string;title:string;description:string;startDate:string;endDate:string;status:string}
type Plan={publicId:string;goalPublicId:string;weekStartDate:string;timezone:string;status:string}
type Task={publicId:string;weeklyPlanPublicId:string;title:string;estimatedMinutes:number;difficulty:number;rrule:string;active:boolean;roleCode:string}
type RoleCode='STUDENT'|'FITNESS_USER'|'WORKER'|'EMOTIONAL_SUPPORT_USER'
type Preset={publicId:string;roleCode:RoleCode;roleName:string;name:string;notes:string;estimatedMinutes:number;difficulty:number;plannedLocalTime:string;rrule:string;dimensionCode:string;dimensionWeight:number;experienceReward:number}
type PresetDraw={roleCode:RoleCode;roleName:string;localDate:string;refreshesRemaining:number;items:Preset[]}
type GoalTemplate={roleCode:RoleCode;title:string;description:string;dimensionName:string;durationDays:number;icon:unknown;tasks:string[]}
const roles:{code:RoleCode;name:string;dimension:string}[]=[
  {code:'STUDENT',name:'学生',dimension:'KNOWLEDGE'},
  {code:'FITNESS_USER',name:'健身用户',dimension:'HEALTH'},
  {code:'WORKER',name:'打工人',dimension:'CAREER'},
  {code:'EMOTIONAL_SUPPORT_USER',name:'情绪支持用户',dimension:'WELLBEING'},
]
const goalTemplates:GoalTemplate[]=[
  {roleCode:'STUDENT',title:'四周完成一轮学习复盘',description:'每周完成一次知识整理，并在第 4 周产出一份可回看的复盘笔记。',dimensionName:'知识',durationDays:28,icon:BookOpen,tasks:['每周整理 1 章要点','用 25 分钟做错题回看','周末写 5 行复盘']},
  {roleCode:'FITNESS_USER',title:'建立温和的身体照顾习惯',description:'以不透支为前提，每周完成 3 次低压力训练或恢复行动。',dimensionName:'健康',durationDays:28,icon:Dumbbell,tasks:['20 分钟轻训练','训练后记录感受','每周安排 1 次恢复']},
  {roleCode:'WORKER',title:'推进一个可交付的职场成果',description:'把一个工作成果拆成每周可验证的小交付，减少临时抱佛脚。',dimensionName:'职业',durationDays:28,icon:BriefcaseBusiness,tasks:['明确本周交付物','每天推进一个 25 分钟片段','周五整理风险']},
  {roleCode:'EMOTIONAL_SUPPORT_USER',title:'建立一套情绪支持流程',description:'在四周内形成可重复的自我照顾、求助和复盘方式。',dimensionName:'情绪',durationDays:28,icon:HeartPulse,tasks:['写下今日状态','准备可信任联系人','复盘一次恢复经验']},
]
const roleNames=Object.fromEntries(roles.map(role=>[role.code,role.name]))
const rruleOptions=[
  ['FREQ=DAILY','每天'],['FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR','每个工作日'],
  ['FREQ=WEEKLY;BYDAY=MO,WE,FR','每周一、三、五'],['FREQ=WEEKLY;BYDAY=TU,TH','每周二、四'],
  ['FREQ=WEEKLY;BYDAY=TU,TH,SA','每周二、四、六'],['FREQ=WEEKLY;BYDAY=WE,SA','每周三、六'],
  ['FREQ=WEEKLY;BYDAY=FR','每周五'],['FREQ=WEEKLY;BYDAY=SU','每周日'],
  ['FREQ=WEEKLY;BYDAY=MO,TH','每周一、四'],['FREQ=WEEKLY;BYDAY=TU,FR','每周二、五'],
  ['FREQ=WEEKLY;BYDAY=MO,WE','每周一、三'],['FREQ=WEEKLY;BYDAY=MO,FR','每周一、五'],
  ['FREQ=WEEKLY;BYDAY=TH','每周四'],['FREQ=WEEKLY;BYDAY=SA','每周六'],
  ['FREQ=WEEKLY;BYDAY=TU,SA','每周二、六'],
]
const goals=ref<Goal[]>([]),dimensions=ref<any[]>([]),plans=ref<Plan[]>([]),tasks=ref<Task[]>([])
const panel=ref<'goal'|'plan'|'task'|null>(null),error=ref(''),busy=ref(false)
const feedback=ref<{tone:'support'|'celebrate';text:string}|null>(null)
const goalPrompt=ref(encouragement('goalDraft'))
const selectedRole=ref<RoleCode>('STUDENT'),presetDraw=ref<PresetDraw|null>(null),presetsLoading=ref(false),presetError=ref('')
const goalForm=reactive({dimensionPublicId:'',title:'',description:'',startDate:today(),endDate:''})
const planForm=reactive({goalPublicId:'',weekStartDate:monday(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone})
const taskForm=reactive({weeklyPlanPublicId:'',title:'',notes:'',estimatedMinutes:25,difficulty:2,rrule:'FREQ=DAILY',plannedLocalTime:'19:00',activeFrom:today(),activeUntil:'',sourceTemplatePublicId:'',roleCode:'STUDENT' as RoleCode,dimensionCode:'KNOWLEDGE',dimensionWeight:10})
const planGoals=computed(()=>new Map(goals.value.map(goal=>[goal.publicId,goal.title])))

function formatLocalDate(date:Date){const year=date.getFullYear();const month=String(date.getMonth()+1).padStart(2,'0');const day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`}
function today(){return formatLocalDate(new Date())}
function monday(){const date=new Date();const day=date.getDay()||7;date.setDate(date.getDate()-day+1);return formatLocalDate(date)}
function plusDays(value:string,days:number){const date=new Date(`${value}T00:00:00`);date.setDate(date.getDate()+days);return formatLocalDate(date)}
async function load(){try{[goals.value,dimensions.value,plans.value,tasks.value]=await Promise.all([api.get<Goal[]>('/goals'),api.get<any[]>('/dimensions'),api.get<Plan[]>('/plans/weekly'),api.get<Task[]>('/tasks')]);goalForm.dimensionPublicId ||= dimensions.value[0]?.publicId;planForm.goalPublicId ||= goals.value.find(g=>g.status==='ACTIVE')?.publicId||goals.value[0]?.publicId;taskForm.weeklyPlanPublicId ||= plans.value[0]?.publicId}catch{error.value='目标与计划暂时无法加载'}}
function openGoal(){goalPrompt.value=encouragement('goalDraft');feedback.value=null;panel.value='goal'}
async function openTask(){feedback.value=null;panel.value='task';await loadPresets(false)}
async function loadPresets(refresh:boolean){presetsLoading.value=true;presetError.value='';try{presetDraw.value=refresh?await api.post<PresetDraw>(`/task-presets/refresh?role=${selectedRole.value}`):await api.get<PresetDraw>(`/task-presets?role=${selectedRole.value}`)}catch(err:any){presetError.value=err?.code==='TASK_PRESET_REFRESH_LIMIT'?'今天的换一批机会已经用完了':'职业任务暂时无法加载，请稍后重试'}finally{presetsLoading.value=false}}
async function chooseRole(role:typeof roles[number]){selectedRole.value=role.code;taskForm.roleCode=role.code;taskForm.dimensionCode=role.dimension;taskForm.dimensionWeight=10;taskForm.sourceTemplatePublicId='';await loadPresets(false)}
function choosePreset(preset:Preset){taskForm.title=preset.name;taskForm.notes=preset.notes;taskForm.estimatedMinutes=preset.estimatedMinutes;taskForm.difficulty=preset.difficulty;taskForm.rrule=preset.rrule;taskForm.plannedLocalTime=preset.plannedLocalTime.slice(0,5);taskForm.sourceTemplatePublicId=preset.publicId;taskForm.roleCode=preset.roleCode;taskForm.dimensionCode=preset.dimensionCode;taskForm.dimensionWeight=preset.dimensionWeight}
function rruleLabel(value:string){return rruleOptions.find(option=>option[0]===value)?.[1]||'自定义重复'}
function applyGoalTemplate(template:GoalTemplate){const dimension=dimensions.value.find(d=>String(d.name).includes(template.dimensionName))||dimensions.value[0];goalForm.dimensionPublicId=dimension?.publicId||goalForm.dimensionPublicId;goalForm.title=template.title;goalForm.description=template.description;goalForm.startDate=today();goalForm.endDate=plusDays(goalForm.startDate,template.durationDays-1);selectedRole.value=template.roleCode;goalPrompt.value=`建议先从这三件事开始：${template.tasks.join('、')}。`;feedback.value=null;panel.value='goal'}
async function createGoal(){busy.value=true;error.value='';try{await api.post('/goals',goalForm);panel.value=null;feedback.value={tone:'support',text:encouragement('goalCreated')};await load()}catch{error.value='目标未保存，请检查日期与内容'}finally{busy.value=false}}
async function createPlan(){busy.value=true;error.value='';try{await api.post('/plans/weekly',planForm);panel.value=null;feedback.value={tone:'support',text:encouragement('planCreated')};await load()}catch{error.value='周计划未保存，请检查目标与周起始日'}finally{busy.value=false}}
async function createTask(){busy.value=true;error.value='';try{await api.post('/tasks',{weeklyPlanPublicId:taskForm.weeklyPlanPublicId,title:taskForm.title,notes:taskForm.notes,estimatedMinutes:taskForm.estimatedMinutes,difficulty:taskForm.difficulty,rrule:taskForm.rrule,plannedLocalTime:taskForm.plannedLocalTime,activeFrom:taskForm.activeFrom,activeUntil:taskForm.activeUntil||plusDays(taskForm.activeFrom,6),sourceTemplatePublicId:taskForm.sourceTemplatePublicId||null,roleCode:taskForm.roleCode,dimensionWeights:{[taskForm.dimensionCode]:taskForm.dimensionWeight}});panel.value=null;feedback.value={tone:'support',text:encouragement('taskCreated')};await load()}catch{error.value='任务未保存，请检查重复规则和日期'}finally{busy.value=false}}
async function materialize(plan:Plan){try{await api.post(`/plans/weekly/${plan.publicId}/materialize`);feedback.value={tone:'support',text:'本周的行动已经准备好了。把注意力交给今天这一小步。'}}catch{error.value='本周日程暂时无法生成，请重试'}}
async function status(goal:Goal,action:string){try{goal.status=(await api.post<any>(`/goals/${goal.publicId}/${action}`)).status;if(action==='complete')feedback.value={tone:'celebrate',text:encouragement('goalCompleted')}}catch{error.value='目标状态暂时无法更新，请重试'}}
onMounted(load)
</script>

<template><section class="page"><header class="page-head"><div><p class="eyebrow">四周目标、周计划与可执行任务</p><h1>目标与计划</h1></div><div class="actions"><button class="secondary" @click="goals.length ? panel='plan' : error='请先创建一个目标'"><CalendarPlus :size="17"/> 周计划</button><button class="secondary" @click="plans.length ? openTask() : error='请先创建周计划'"><ListPlus :size="17"/> 任务</button><button class="primary" @click="openGoal"><Plus :size="17"/> 目标</button></div></header><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="feedback" class="feedback-banner" :data-tone="feedback.tone" role="status" aria-live="polite"><Sparkles :size="19"/><p>{{feedback.text}}</p></div>

<section class="template-band band" aria-labelledby="template-title"><div class="template-head"><div><p class="eyebrow">目标模板</p><h2 id="template-title">从一个可修改的场景包开始</h2></div><span>选择后仍需你确认保存</span></div><div class="template-grid"><button v-for="template in goalTemplates" :key="template.roleCode" type="button" class="template-card" @click="applyGoalTemplate(template)"><span class="template-icon"><component :is="template.icon" :size="20"/></span><span class="template-copy"><strong>{{template.title}}</strong><small>{{template.description}}</small></span><span class="template-tasks"><span v-for="task in template.tasks" :key="task">{{task}}</span></span></button></div></section>

<section class="guide-band band" aria-labelledby="goal-guide-title"><div class="guide-title"><ListChecks :size="19"/><div><p class="eyebrow">操作指引</p><h2 id="goal-guide-title">让目标出现在今日，需要先生成日程</h2></div></div><div class="guide-steps"><span>建目标</span><ArrowRight :size="15"/><span>建周计划</span><ArrowRight :size="15"/><span>添加任务</span><ArrowRight :size="15"/><span>生成本周日程</span><ArrowRight :size="15"/><span>今日页显示当天安排</span></div><p class="guide-note">当前数据流是正常连通的：目标页保存目标、周计划和任务定义；点击“生成本周日程”后，系统会把任务展开到具体日期，今日页只读取今天的日程。</p></section>

<form v-if="panel==='goal'" class="band stack" @submit.prevent="createGoal"><div><h2>新建目标</h2><p class="support-line"><Sparkles :size="16"/>{{goalPrompt}}</p></div><div class="field"><label for="dimension">成长维度</label><select id="dimension" v-model="goalForm.dimensionPublicId"><option v-for="d in dimensions" :key="d.publicId" :value="d.publicId">{{d.name}}</option></select></div><div class="field"><label for="goal-title">目标名称</label><input id="goal-title" v-model="goalForm.title" required maxlength="160"></div><div class="field"><label for="goal-description">完成标准</label><textarea id="goal-description" v-model="goalForm.description"></textarea></div><div class="split"><div class="field"><label for="goal-start">开始日期</label><input id="goal-start" v-model="goalForm.startDate" type="date" required></div><div class="field"><label for="goal-end">结束日期</label><input id="goal-end" v-model="goalForm.endDate" type="date" required></div></div><div class="actions"><button class="primary" :disabled="busy">保存目标</button><button type="button" class="secondary" @click="panel=null">取消</button></div></form>

<form v-else-if="panel==='plan'" class="band stack" @submit.prevent="createPlan"><h2>安排一周</h2><div class="field"><label for="plan-goal">关联目标</label><select id="plan-goal" v-model="planForm.goalPublicId" required><option v-for="g in goals" :key="g.publicId" :value="g.publicId">{{g.title}}</option></select></div><div class="split"><div class="field"><label for="week-start">周一日期</label><input id="week-start" v-model="planForm.weekStartDate" type="date" required></div><div class="field"><label for="timezone">时区</label><input id="timezone" v-model="planForm.timezone" required></div></div><div class="actions"><button class="primary" :disabled="busy">保存周计划</button><button type="button" class="secondary" @click="panel=null">取消</button></div></form>

<form v-else-if="panel==='task'" class="band stack task-builder" @submit.prevent="createTask"><div class="task-builder-head"><div><h2>添加可执行任务</h2><p>先从职业任务中挑一个，也可以继续修改细节。想在今日页立刻看到，请确认开始日期和重复规则覆盖今天。</p></div><span v-if="presetDraw" class="refresh-quota">今日还可换 {{presetDraw.refreshesRemaining}} 次</span></div><div class="role-tabs" aria-label="选择职业"><button v-for="role in roles" :key="role.code" type="button" :class="{active:selectedRole===role.code}" :aria-pressed="selectedRole===role.code" @click="chooseRole(role)">{{role.name}}</button></div><div class="preset-toolbar"><strong>{{roleNames[selectedRole]}}任务</strong><button type="button" class="secondary refresh-button" :disabled="presetsLoading||!presetDraw?.refreshesRemaining" @click="loadPresets(true)"><RefreshCw :size="16" :class="{spinning:presetsLoading}"/> 换一批</button></div><p v-if="presetError" class="error compact-error" role="alert">{{presetError}}</p><p v-if="presetsLoading&&!presetDraw" class="preset-loading">正在准备四个任务…</p><div v-else-if="presetDraw" class="preset-list"><button v-for="preset in presetDraw.items" :key="preset.publicId" type="button" class="preset-item" :class="{selected:taskForm.sourceTemplatePublicId===preset.publicId}" :aria-pressed="taskForm.sourceTemplatePublicId===preset.publicId" @click="choosePreset(preset)"><span class="preset-main"><span class="preset-title"><Check v-if="taskForm.sourceTemplatePublicId===preset.publicId" :size="16"/>{{preset.name}}</span><small>{{preset.notes}}</small></span><span class="preset-meta"><span>{{preset.estimatedMinutes}} 分钟</span><span>难度 {{preset.difficulty}}</span><span>{{preset.plannedLocalTime.slice(0,5)}}</span><span>{{rruleLabel(preset.rrule)}}</span><b>+{{preset.experienceReward}} 经验</b></span></button></div><div class="task-fields"><div class="field"><label for="task-plan">周计划</label><select id="task-plan" v-model="taskForm.weeklyPlanPublicId" required><option v-for="p in plans" :key="p.publicId" :value="p.publicId">{{planGoals.get(p.goalPublicId)}} · {{p.weekStartDate}}</option></select></div><div class="field"><label for="task-title">任务名称</label><input id="task-title" v-model="taskForm.title" required maxlength="160"></div><div class="split compact"><div class="field"><label for="task-minutes">预计分钟</label><input id="task-minutes" v-model.number="taskForm.estimatedMinutes" type="number" min="5" max="240"></div><div class="field"><label for="task-difficulty">难度（1–3）</label><input id="task-difficulty" v-model.number="taskForm.difficulty" type="number" min="1" max="3"></div></div><div class="split"><div class="field"><label for="task-time">计划时间</label><input id="task-time" v-model="taskForm.plannedLocalTime" type="time" required></div><div class="field"><label for="task-rule">重复规则</label><select id="task-rule" v-model="taskForm.rrule"><option v-for="option in rruleOptions" :key="option[0]" :value="option[0]">{{option[1]}}</option></select></div></div><div class="field"><label for="task-notes">备注</label><textarea id="task-notes" v-model="taskForm.notes"></textarea></div></div><div class="actions"><button class="primary" :disabled="busy">保存任务</button><button type="button" class="secondary" @click="panel=null">取消</button></div></form>

<section class="workspace"><div><h2>目标清单</h2><div v-if="goals.length" class="goal-grid"><article v-for="goal in goals" :key="goal.publicId"><div class="goal-top"><span class="status">{{goal.status}}</span><div class="goal-actions"><button v-if="goal.status==='ACTIVE'" class="icon-button" title="暂停目标" aria-label="暂停目标" @click="status(goal,'pause')"><Pause :size="17"/></button><button v-else-if="goal.status==='PAUSED'" class="icon-button" title="恢复目标" aria-label="恢复目标" @click="status(goal,'resume')"><Play :size="17"/></button><button v-if="goal.status==='ACTIVE'||goal.status==='PAUSED'" class="icon-button complete-goal" title="完成目标" aria-label="完成目标" @click="status(goal,'complete')"><CheckCircle2 :size="18"/></button></div></div><h3>{{goal.title}}</h3><p>{{goal.description||'尚未填写完成标准'}}</p><small>{{goal.startDate}} 至 {{goal.endDate}}</small></article></div><p v-else class="empty">还没有目标。先定义一个 14–84 天的清晰结果。</p></div>
<div><h2>周计划与任务</h2><div v-if="plans.length" class="plan-list"><article v-for="plan in plans" :key="plan.publicId"><header><div><strong>{{planGoals.get(plan.goalPublicId)}}</strong><small>{{plan.weekStartDate}} · {{plan.timezone}}</small></div><button class="secondary" @click="materialize(plan)">生成本周日程</button></header><ul><li v-for="task in tasks.filter(item=>item.weeklyPlanPublicId===plan.publicId)" :key="task.publicId"><span>{{task.title}}</span><small>{{roleNames[task.roleCode]||'学生'}} · {{task.estimatedMinutes}} 分钟 · 难度 {{task.difficulty}}</small></li></ul><p v-if="!tasks.some(item=>item.weeklyPlanPublicId===plan.publicId)" class="muted">尚未添加任务</p></article></div><p v-else class="empty">创建目标后，为它安排一周。</p></div></section></section></template>

<style scoped>.template-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:14px}.template-head h2{margin:0}.template-head span{color:var(--muted);font-size:13px;white-space:nowrap}.template-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.template-card{min-height:190px;display:grid;grid-template-rows:auto auto 1fr;gap:12px;align-items:start;padding:14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);color:var(--ink);text-align:left}.template-icon{width:34px;height:34px;display:grid;place-items:center;border:1px solid color-mix(in srgb,var(--primary) 28%,var(--border));border-radius:var(--radius);color:var(--primary);background:color-mix(in srgb,var(--primary) 7%,var(--surface))}.template-copy{display:grid;gap:7px}.template-copy strong{line-height:1.35}.template-copy small{color:var(--muted);line-height:1.5}.template-tasks{align-self:end;display:grid;gap:5px;color:var(--muted);font-size:12px}.template-tasks span{padding-left:9px;border-left:2px solid color-mix(in srgb,var(--primary) 26%,var(--border))}.guide-band{display:grid;gap:12px}.guide-title{display:flex;align-items:center;gap:10px}.guide-title svg{color:var(--primary)}.guide-title h2{margin:0}.guide-steps{display:flex;align-items:center;flex-wrap:wrap;gap:8px;color:var(--muted);font-size:13px}.guide-steps span{min-height:30px;display:inline-flex;align-items:center;padding:0 10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface)}.guide-steps svg{color:var(--primary)}.guide-note{max-width:760px;margin:0;color:var(--muted);line-height:1.65}.workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,1.1fr);gap:32px;margin-top:28px}.workspace h2,.band h2{font-size:18px}.goal-grid{display:grid;gap:10px}.goal-grid article{border:1px solid var(--border);border-radius:var(--radius);padding:16px;background:var(--surface)}.goal-grid article:hover{border-color:color-mix(in srgb,var(--primary) 32%,var(--border));background:color-mix(in srgb,var(--primary) 4%,var(--surface))}.goal-top,.plan-list header{display:flex;justify-content:space-between;align-items:start;gap:12px}.goal-actions{display:flex;gap:6px}.goal-actions .icon-button{border:1px solid var(--border)}.goal-actions .complete-goal{color:var(--primary);border-color:color-mix(in srgb,var(--primary) 28%,var(--border))}.goal-grid h3{font-size:17px;margin:10px 0}.goal-grid p{color:var(--muted);line-height:1.6;min-height:42px}.goal-grid small,.plan-list small{display:block;color:var(--muted);font-size:12px}.plan-list{border-top:1px solid var(--border)}.plan-list article{padding:16px 0;border-bottom:1px solid var(--border)}.plan-list ul{list-style:none;padding:0;margin:12px 0 0}.plan-list li{display:flex;justify-content:space-between;gap:16px;padding:9px 0;border-top:1px solid var(--surface-muted)}.support-line{display:flex;align-items:flex-start;gap:8px;max-width:680px;margin:7px 0 0;color:var(--primary);font-family:Georgia,"Songti SC",serif;line-height:1.65}.support-line svg{flex:none;margin-top:4px}.compact{grid-template-columns:repeat(2,minmax(0,180px))}.task-builder-head,.preset-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px}.task-builder-head p{margin:5px 0 0;color:var(--muted);font-size:13px}.refresh-quota{color:var(--muted);font-size:13px;white-space:nowrap}.role-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--border);border-radius:var(--radius);overflow:hidden}.role-tabs button{border:0;border-right:1px solid var(--border);border-radius:0;background:var(--surface);color:var(--muted);padding:0 10px}.role-tabs button:last-child{border-right:0}.role-tabs button.active{background:var(--primary);color:white;font-weight:700}.refresh-button{display:inline-flex;align-items:center;gap:7px}.preset-list{display:grid;border-top:1px solid var(--border)}.preset-item{display:grid;grid-template-columns:minmax(0,1fr) auto;ali